// Generated by scripts/generate-icons.mjs. Edit that script to change the icon.
export const iconPngBase64 = Object.freeze({
  "apple-touch-icon.png": "",
  "icon-192.png": "",
  "icon-512.png": ""
});

export const iconPngBytes = (filename) => {
  const encoded = iconPngBase64[filename];
  if (!encoded) return null;
  return Uint8Array.from(atob(encoded), (char) => char.charCodeAt(0));
};
